// API keys live in the Windows Credential Manager, never on disk and never in
// the front end: the settings page can store, replace or remove a key and ask
// whether one is there, but it can never read one back.

use keyring::Entry;

/// Credential Manager "service" the entries are filed under.
const SERVICE: &str = "dev.abdelrhman.tute";

/// Provider ids are generated by the settings page; anything that doesn't look
/// like one is refused rather than used as a Credential Manager name.
fn valid_provider_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 40
        && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}

fn entry(provider_id: &str) -> Result<Entry, String> {
    if !valid_provider_id(provider_id) {
        return Err(format!("invalid provider id {provider_id:?}"));
    }
    Entry::new(SERVICE, &format!("provider:{provider_id}")).map_err(|e| e.to_string())
}

/// The key for a provider, if one is stored. Rust-side only.
pub fn get(provider_id: &str) -> Option<String> {
    entry(provider_id).ok()?.get_password().ok().filter(|v| !v.is_empty())
}

/// Stores (or, with an empty value, removes) a provider's key.
pub fn set(provider_id: &str, value: &str) -> Result<(), String> {
    if value.trim().is_empty() {
        return clear(provider_id);
    }
    entry(provider_id)?.set_password(value.trim()).map_err(|e| e.to_string())
}

pub fn clear(provider_id: &str) -> Result<(), String> {
    match entry(provider_id)?.delete_credential() {
        Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
        Err(e) => Err(e.to_string()),
    }
}

pub fn present(provider_id: &str) -> bool {
    get(provider_id).is_some()
}

// ── Connected services (Linear…) ────────────────────────────────────────────

fn service_entry(name: &str) -> Result<Entry, String> {
    if !valid_provider_id(name) {
        return Err(format!("invalid service name {name:?}"));
    }
    Entry::new(SERVICE, &format!("service:{name}")).map_err(|e| e.to_string())
}

/// A connected service's stored credentials (its tokens, as JSON). Rust-side only.
pub fn service_get(name: &str) -> Option<String> {
    service_entry(name).ok()?.get_password().ok().filter(|v| !v.is_empty())
}

pub fn service_set(name: &str, value: &str) -> Result<(), String> {
    service_entry(name)?.set_password(value).map_err(|e| e.to_string())
}

pub fn service_clear(name: &str) -> Result<(), String> {
    match service_entry(name)?.delete_credential() {
        Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
        Err(e) => Err(e.to_string()),
    }
}

#[cfg(test)]
mod tests {
    use super::valid_provider_id;

    #[test]
    fn provider_ids_are_checked() {
        assert!(valid_provider_id("p-lq3k9x"));
        assert!(!valid_provider_id(""));
        assert!(!valid_provider_id("../other"));
        assert!(!valid_provider_id("a b"));
        assert!(!valid_provider_id(&"x".repeat(41)));
    }
}
